const project = await response.json();
app.innerHTML = `<button id="back" type="button">Projects</button><h1>${escapeText(project.name)}</h1>
  <form id="task-form"><label for="task-title">Task title</label><input id="task-title" name="title" type="text"><button type="submit">Create task</button></form>
  <p id="alert" role="alert" hidden></p><label for="task-filter">Task filter</label>
  <select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select>
  <section id="tasks" aria-label="Tasks"></section>`;
app.querySelector('#back').addEventListener('click', () => { location.href = '/'; });
const alert = app.querySelector('#alert');
const filter = app.querySelector('#task-filter');
async function renderTasks() {
  const tasksResponse = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`);
  const tasks = await tasksResponse.json();
  const visible = tasks.filter(task => filter.value === 'All' || (filter.value === 'Completed') === Boolean(task.completed));
  const list = app.querySelector('#tasks');
  list.replaceChildren();
  for (const task of visible) {
    const row = document.createElement('div');
    row.dataset.testid = 'task-row';
    row.className = 'task-row';
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = Boolean(task.completed);
    checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    const label = document.createElement('label');
    label.textContent = task.title;
    row.append(checkbox, label);
    checkbox.addEventListener('change', async () => {
      await fetch(`/api/projects/${id}/tasks/${task.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
      await renderTasks();
    });
    list.append(row);
  }
}
filter.addEventListener('change', renderTasks);
app.querySelector('#task-form').addEventListener('submit', async event => {
  event.preventDefault();
  const title = app.querySelector('#task-title').value.trim();
  if (!title) { alert.textContent = 'Task title is required'; alert.hidden = false; return; }
  const created = await fetch(`/api/projects/${id}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }) });
  if (!created.ok) { const result = await created.json(); alert.textContent = result.error || 'Unable to create task'; alert.hidden = false; return; }
  alert.hidden = true;
  app.querySelector('#task-title').value = '';
  await renderTasks();
});
await renderTasks();

